package com.mzmiyazxakii.spin.client;
import com.mzmiyazxakii.spin.SpinMod;import net.minecraft.client.Minecraft;import net.minecraft.client.KeyMapping;import net.minecraftforge.api.distmarker.Dist;import net.minecraftforge.event.TickEvent;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.fml.common.Mod;import org.lwjgl.glfw.GLFW;
@Mod.EventBusSubscriber(modid=SpinMod.MOD_ID,value=Dist.CLIENT)public final class SpinSkinKeyHandler{public static final KeyMapping OPEN_SKINS=new KeyMapping("key.spin.open_skins",GLFW.GLFW_KEY_P,"key.categories.spin");private SpinSkinKeyHandler(){}@SubscribeEvent public static void tick(TickEvent.ClientTickEvent e){if(e.phase!=TickEvent.Phase.END)return;Minecraft m=Minecraft.getInstance();while(OPEN_SKINS.consumeClick()){if(m.player==null||m.screen!=null)continue;var a=m.player.getMainHandItem();var b=m.player.getOffhandItem();if(a.is(SpinMod.STEEL_BALL.get()))m.setScreen(new SpinSkinScreen(a));else if(b.is(SpinMod.STEEL_BALL.get()))m.setScreen(new SpinSkinScreen(b));}}}